INSERT INTO chapters(module_id,title,title_translation,description,description_translation,planned_lesson_count,difficulty_min,difficulty_max,sort_order,status,metadata) VALUES(v_module,'Wohnort in Berlin','محل زندگی در برلین','Raha spricht mit Lena über ihren neuen Wohnort und überträgt Name, Herkunft und Wohnort später selbstständig auf das Hausbüro.','رها با لنا درباره محل زندگی تازه‌اش حرف می‌زند و بعد نام، مبدأ و محل زندگی را مستقل در دفتر ساختمان به کار می‌برد.',4,1,1,3,'validated',JSON_OBJECT('series',3,'contractVersion','3.0.0','foundationRevision','3.2.0','qualityRevision','3.2.1'));
