INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES
(v_chapter,v_c_lena,v_c_raha,'Wo wohnst du?','کجا زندگی می‌کنی؟','Lena fragt Raha nach ihrer neuen Wohnung in Berlin.','لنا درباره محل زندگی تازه رها در برلین می‌پرسد.','story','berlin_new_start',9,1,420,1,'validated',JSON_OBJECT('pedagogicalRole','exposure')),
(v_chapter,v_c_lena,v_c_raha,'Ich wohne in Berlin','من در برلین زندگی می‌کنم','Raha bemerkt das Muster wohnen in + Ort und übt natürliche Varianten.','رها الگوی wohnen in + مکان را می‌بیند و شکل‌های طبیعی آن را تمرین می‌کند.','story','berlin_new_start',10,1,420,2,'validated',JSON_OBJECT('pedagogicalRole','explicit_form')),
(v_chapter,v_c_lena,v_c_raha,'Name, Herkunft, Wohnort','نام، مبدأ و محل زندگی','Raha ruft bekannte Informationen ab und verbindet sie mit dem neuen Wohnort.','رها اطلاعات قبلی را بازیابی می‌کند و با محل زندگی تازه ترکیب می‌کند.','story','berlin_new_start',11,1,420,3,'validated',JSON_OBJECT('pedagogicalRole','retrieval')),
(v_chapter,v_c_keller,v_c_raha,'Im Hausbüro','در دفتر ساختمان','Raha beantwortet bei einer neuen Ansprechperson selbstständig Fragen zu Name, Herkunft und Wohnort.','رها نزد مسئول تازه ساختمان، مستقل به پرسش‌های نام، مبدأ و محل زندگی پاسخ می‌دهد.','story','berlin_new_start',12,1,480,4,'validated',JSON_OBJECT('pedagogicalRole','mastery'));
