INSERT INTO activities(lesson_id,activity_type,sort_order,prompt,instruction,difficulty,config,metadata) VALUES
(v_l_1,'listen',1,'Wo wohnst du?','اول گوش کن و منظور سوال را بگیر.',1,CAST('{"mode":"audio_first","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',3)),(v_l_1,'new_word',2,'Ich wohne in ...','الگوی گفتن محل زندگی را به صورت یک تکه یاد بگیر.',1,CAST('{"mode":"chunk_teach","unit_key":"de:a1:ich-wohne-in","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',3)),(v_l_1,'pronunciation',3,'wohne','صدای واکه بلند o را بشنو، تفاوتش با o کوتاه را توجه کن، بعد بگو.',1,CAST('{"mode":"sound_notice","target":"long_o_wohnen","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',3)),(v_l_1,'speak',4,'Ich wohne in Berlin.','یک بار واضح تولید کن.',1,CAST('{"mode":"repeat_visible","accepted":["Ich wohne in Berlin.","Ich wohne jetzt in Berlin."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_1,'speak',5,'بگو در برلین زندگی می‌کنی.','بدون جمله آلمانی نمایان جواب بده.',1,CAST('{"mode":"recall_hidden","cue_fa":"بگو در برلین زندگی می‌کنی.","accepted":["Ich wohne in Berlin.","Ich wohne jetzt in Berlin."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_1,'meaning_choice',6,'Ich ___ in Berlin.','فعل درست را انتخاب کن.',1,CAST('{"mode":"sentence_blank","options":["wohne","spreche","komme"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_1,'reading',7,'Raha wohnt in Berlin. Lena wohnt auch in Berlin.','متن کوتاه را بخوان.',1,CAST('{"mode":"reading_input","text":"Raha wohnt in Berlin. Lena wohnt auch in Berlin.","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',3)),(v_l_1,'reading_comprehension',8,'Wo wohnt Raha?','اطلاعات را از متن پیدا کن.',1,CAST('{"mode":"reading_inference","options":["in Berlin","im Iran","in Deutschland"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_1,'word_order',9,'Ich wohne in Berlin','کلمات را مرتب کن.',1,CAST('{"mode":"tap_tokens","tokens":["Berlin","wohne","Ich","in"],"answer":["Ich","wohne","in","Berlin"],"input":"tap_tokens","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_1,'speak',10,'یک همسایه تازه می‌پرسد کجا زندگی می‌کنی.','طبیعی و کوتاه جواب بده.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"یک همسایه تازه می‌پرسد کجا زندگی می‌کنی.","accepted_intents":["Ich wohne in Berlin.","Hier in Berlin."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_1,'speak',11,'از طرف مقابل بپرس کجا زندگی می‌کند.','سوال را مستقل بساز.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"از طرف مقابل بپرس کجا زندگی می‌کند.","accepted_intents":["Wo wohnst du?","Und wo wohnst du?"],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_1,'speak',12,'نام و محل زندگی‌ات را با هم بگو.','دو اطلاعات را ترکیب کن.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"نام و محل زندگی‌ات را با هم بگو.","accepted_intents":["Ich heiße Raha. Ich wohne in Berlin.","Ich bin Raha und wohne in Berlin."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3));
INSERT INTO activities(lesson_id,activity_type,sort_order,prompt,instruction,difficulty,config,metadata) VALUES
(v_l_2,'listen',1,'Ich wohne in Berlin.','گوش کن و الگوی جمله را تشخیص بده.',1,CAST('{"mode":"audio_first","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',3)),(v_l_2,'new_word',2,'Wo wohnst du?','الگوی پرسیدن محل زندگی را یاد بگیر.',1,CAST('{"mode":"chunk_teach","unit_key":"de:a1:wo-wohnst-du","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',3)),(v_l_2,'pronunciation',3,'wohnen','o بلند را بشنو، توجه کن و بعد تولید کن.',1,CAST('{"mode":"sound_notice","target":"long_o_wohnen","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',3)),(v_l_2,'speak',4,'Wo wohnst du?','سوال را واضح تکرار کن.',1,CAST('{"mode":"repeat_visible","accepted":["Wo wohnst du?","Und wo wohnst du?"],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_2,'speak',5,'بپرس کجا زندگی می‌کنی؟','از حافظه بگو.',1,CAST('{"mode":"recall_hidden","cue_fa":"بپرس کجا زندگی می‌کنی؟","accepted":["Wo wohnst du?","Und wo wohnst du?"],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_2,'meaning_choice',6,'Wo ___ du?','شکل درست فعل را انتخاب کن.',1,CAST('{"mode":"sentence_blank","options":["wohnst","kommst","sprichst"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_2,'reading',7,'Adresse: Berlin. Raha wohnt hier.','کارت کوتاه را بخوان.',1,CAST('{"mode":"reading_input","text":"Adresse: Berlin. Raha wohnt hier.","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',3)),(v_l_2,'reading_comprehension',8,'In welcher Stadt wohnt Raha?','شهر را پیدا کن.',1,CAST('{"mode":"reading_inference","options":["Berlin","Teheran","Hamburg"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_2,'word_order',9,'Wo wohnst du','مرتب کن.',1,CAST('{"mode":"tap_tokens","tokens":["du","wohnst","Wo"],"answer":["Wo","wohnst","du"],"input":"tap_tokens","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_2,'speak',10,'دوستت مبدأت را می‌داند؛ فقط محل زندگی فعلی را بگو.','فقط اطلاعات لازم را بده.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"دوستت مبدأت را می‌داند؛ فقط محل زندگی فعلی را بگو.","accepted_intents":["Ich wohne in Berlin.","Jetzt wohne ich in Berlin."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_2,'speak',11,'بگو اهل ایران هستی ولی حالا در برلین زندگی می‌کنی.','دو الگو را ترکیب کن.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"بگو اهل ایران هستی ولی حالا در برلین زندگی می‌کنی.","accepted_intents":["Ich komme aus dem Iran und wohne jetzt in Berlin.","Ich komme aus dem Iran. Jetzt wohne ich in Berlin."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_2,'speak',12,'یک معرفی کوتاه با نام و محل زندگی بساز.','بدون cue آلمانی بگو.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"یک معرفی کوتاه با نام و محل زندگی بساز.","accepted_intents":["Hallo, ich heiße Raha und wohne in Berlin.","Ich bin Raha. Ich wohne in Berlin."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3));
INSERT INTO activities(lesson_id,activity_type,sort_order,prompt,instruction,difficulty,config,metadata) VALUES
(v_l_3,'listen',1,'Wie heißt du? Wo wohnst du?','گوش کن و دو سوال را از هم تشخیص بده.',1,CAST('{"mode":"audio_first","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',3)),(v_l_3,'new_word',2,'Ich heiße ... / Ich wohne in ...','دو الگوی معرفی را کنار هم مرور کن.',1,CAST('{"mode":"chunk_teach","unit_key":"de:a1:ich-wohne-in","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',3)),(v_l_3,'pronunciation',3,'wohne','o بلند را بشنو و تولید کن.',1,CAST('{"mode":"sound_notice","target":"long_o_wohnen","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',3)),(v_l_3,'speak',4,'بگو اسمت رهاست.','مرور due از معرفی نام.',1,CAST('{"mode":"recall_hidden","cue_fa":"بگو اسمت رهاست.","accepted":["Ich heiße Raha.","Ich bin Raha."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_3,'speak',5,'بگو اهل ایران هستی.','مرور due از مبدأ.',1,CAST('{"mode":"recall_hidden","cue_fa":"بگو اهل ایران هستی.","accepted":["Ich komme aus dem Iran.","Aus dem Iran."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_3,'meaning_choice',6,'Ich ___ in Berlin.','فعل محل زندگی را انتخاب کن.',1,CAST('{"mode":"sentence_blank","options":["wohne","heiße","spreche"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_3,'reading',7,'Hallo! Ich heiße Raha. Ich komme aus dem Iran. Jetzt wohne ich in Berlin.','متن معرفی را بخوان.',1,CAST('{"mode":"reading_input","text":"Hallo! Ich heiße Raha. Ich komme aus dem Iran. Jetzt wohne ich in Berlin.","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',3)),(v_l_3,'reading_comprehension',8,'Wo wohnt Raha jetzt?','از متن جواب بده.',1,CAST('{"mode":"reading_inference","options":["in Berlin","im Iran","in Hamburg"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_3,'word_order',9,'Ich wohne in Berlin','مرتب کن.',1,CAST('{"mode":"tap_tokens","tokens":["in","Berlin","Ich","wohne"],"answer":["Ich","wohne","in","Berlin"],"input":"tap_tokens","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_3,'speak',10,'صبح با همسایه‌ای روبه‌رو شو، سلام کن و نامت را بگو.','review واقعی Series 1 را در موقعیت تازه انجام بده.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"صبح با همسایه‌ای روبه‌رو شو، سلام کن و نامت را بگو.","accepted_intents":["Guten Morgen! Ich heiße Raha.","Hallo! Ich bin Raha."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_3,'speak',11,'همسایه درباره مبدأ و زبانت می‌پرسد؛ هر دو را جواب بده.','review واقعی Series 2 را ترکیب کن.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"همسایه درباره مبدأ و زبانت می‌پرسد؛ هر دو را جواب بده.","accepted_intents":["Ich komme aus dem Iran und spreche Persisch.","Ich komme aus dem Iran. Ich spreche Persisch."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_3,'speak',12,'نام، مبدأ، زبان و محل زندگی را در یک معرفی تازه ترکیب کن.','بدون جمله نمونه پاسخ بده.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"نام، مبدأ، زبان و محل زندگی را در یک معرفی تازه ترکیب کن.","accepted_intents":["Ich heiße Raha, komme aus dem Iran, spreche Persisch und wohne in Berlin.","Hallo, ich bin Raha. Ich komme aus dem Iran. Ich spreche Persisch und wohne in Berlin."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3));
INSERT INTO activities(lesson_id,activity_type,sort_order,prompt,instruction,difficulty,config,metadata) VALUES
(v_l_4,'listen',1,'Guten Tag. Sie sind neu im Haus?','گوش کن و موقعیت رسمی‌تر تازه را بفهم.',1,CAST('{"mode":"audio_first","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',3)),(v_l_4,'reading',2,'Hausbüro – Anmeldung: Name, Herkunft, Wohnort','تابلوی کوتاه را بخوان.',1,CAST('{"mode":"reading_input","text":"Hausbüro – Anmeldung: Name, Herkunft, Wohnort","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',3)),(v_l_4,'reading_comprehension',3,'Welche Information wird gefragt?','از تابلو نتیجه بگیر.',1,CAST('{"mode":"reading_inference","options":["Wohnort","Lieblingsessen","Beruf"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_4,'new_word',4,'Ich wohne in ...','الگوی محل زندگی را کوتاه مرور کن.',1,CAST('{"mode":"chunk_teach","unit_key":"de:a1:ich-wohne-in","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',3)),(v_l_4,'pronunciation',5,'wohne','o بلند را بشنو، توجه کن و واضح تولید کن.',1,CAST('{"mode":"sound_notice","target":"long_o_wohnen","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',3)),(v_l_4,'speak',6,'Ich wohne hier in Berlin.','یک بار واضح تولید کن.',1,CAST('{"mode":"repeat_visible","accepted":["Ich wohne hier in Berlin.","Ich wohne in Berlin."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_4,'speak',7,'مسئول ساختمان نامت را می‌پرسد.','فقط نامت را طبیعی بگو.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"مسئول ساختمان نامت را می‌پرسد.","accepted_intents":["Ich heiße Raha.","Ich bin Raha."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_4,'speak',8,'بعد درباره مبدأت می‌پرسد.','بدون cue آلمانی جواب بده.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"مسئول درباره مبدأت می‌پرسد.","accepted_intents":["Ich komme aus dem Iran.","Aus dem Iran."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_4,'meaning_choice',9,'Ich ___ in Berlin.','انتخاب کن.',1,CAST('{"mode":"sentence_blank","options":["wohne","komme","heiße"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_4,'word_order',10,'Wo wohnen Sie','مرتب کن.',1,CAST('{"mode":"tap_tokens","tokens":["Sie","wohnen","Wo"],"answer":["Wo","wohnen","Sie"],"input":"tap_tokens","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_4,'speak',11,'مسئول می‌پرسد الان کجا زندگی می‌کنی.','در register مناسب جواب بده.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"مسئول ساختمان می‌پرسد الان کجا زندگی می‌کنی.","accepted_intents":["Ich wohne hier in Berlin.","Ich wohne in Berlin."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3)),(v_l_4,'speak',12,'بدون کمک، برای ثبت ساختمان نام، مبدأ و محل زندگی را یک‌جا بگو.','novel-context mastery و recombination مستقل.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"برای ثبت ساختمان نام، مبدأ و محل زندگی را یک‌جا بگو.","accepted_intents":["Ich heiße Raha. Ich komme aus dem Iran und wohne in Berlin.","Ich bin Raha, komme aus dem Iran und wohne hier in Berlin."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',3));
INSERT IGNORE INTO sem_lesson_learning_units(lesson_id,learning_unit_id,learning_role,is_target,exposure_count,evidence_activity_ids,metadata) SELECT v_l_1,id,'new',1,2,JSON_ARRAY(),JSON_OBJECT('series',3) FROM sem_learning_units WHERE course_id=v_course AND unit_key IN('de:a1:ich-wohne-in','de:a1:wo-wohnst-du','de:a1:wo-wohnen-sie','de:a1:wohnen-present','de:a1:pron:long-o-wohnen','de:a1:can:residence');
INSERT IGNORE INTO sem_lesson_learning_units(lesson_id,learning_unit_id,learning_role,is_target,exposure_count,evidence_activity_ids,metadata) SELECT v_l_4,id,'mastery',1,1,JSON_ARRAY(),JSON_OBJECT('series',3) FROM sem_learning_units WHERE course_id=v_course AND unit_key IN('de:a1:ich-wohne-in','de:a1:wo-wohnst-du','de:a1:wo-wohnen-sie','de:a1:wohnen-present','de:a1:pron:long-o-wohnen','de:a1:can:residence');
INSERT IGNORE INTO sem_turn_learning_units(turn_id,learning_unit_id,evidence_type,metadata) SELECT t.id,lu.id,'mastery',JSON_OBJECT('series',3) FROM turns t JOIN sem_learning_units lu ON lu.course_id=v_course AND lu.unit_key='de:a1:can:residence' WHERE t.lesson_id=v_l_4 AND t.sort_order=6 LIMIT 1;
INSERT IGNORE INTO sem_review_obligations(course_id,learning_unit_id,origin_chapter_id,due_series,spacing_offset,status,metadata) SELECT v_course,lu.id,v_chapter,3+o.off,o.off,'due',JSON_OBJECT('originSeries',3) FROM sem_learning_units lu JOIN(SELECT 1 off UNION ALL SELECT 2 UNION ALL SELECT 4 UNION ALL SELECT 8 UNION ALL SELECT 16)o WHERE lu.course_id=v_course AND lu.unit_key IN('de:a1:ich-wohne-in','de:a1:wo-wohnst-du','de:a1:wo-wohnen-sie','de:a1:wohnen-present','de:a1:pron:long-o-wohnen','de:a1:can:residence');
